#!/usr/bin/env node
// Packs /data/*.json (and the fonts) into data/bundle.js so index.html works
// when opened straight from disk (file://), where browsers block fetch().
// Re-run after editing any JSON in /data:   node tools/bundle.js
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const DATA = path.join(ROOT, 'data');
const out = {};
for (const f of fs.readdirSync(DATA)) if (f.endsWith('.json')) out[f.replace(/\.json$/, '')] = JSON.parse(fs.readFileSync(path.join(DATA, f), 'utf8'));
for (const f of fs.readdirSync(path.join(DATA, 'maps'))) if (f.endsWith('.json')) out['maps/' + f.replace(/\.json$/, '')] = JSON.parse(fs.readFileSync(path.join(DATA, 'maps', f), 'utf8'));

const fonts = {};
for (const f of ['power green.ttf', 'power green narrow.ttf', 'power red and blue.ttf']) {
  const p = path.join(ROOT, 'assets/fonts', f);
  if (fs.existsSync(p)) fonts['assets/fonts/' + f] = 'data:font/ttf;base64,' + fs.readFileSync(p).toString('base64');
}
const js = `// Generated by tools/bundle.js — do not edit by hand.\nwindow.GEGK_DATA=${JSON.stringify(out)};\nwindow.GEGK_FONTS=${JSON.stringify(fonts)};\n`;
fs.writeFileSync(path.join(DATA, 'bundle.js'), js);
console.log(`data/bundle.js: ${Object.keys(out).length} data files, ${(js.length / 1048576).toFixed(1)} MB`);
